package config

import (
	"os"
	"strconv"
	"time"
)

type Config struct {
	Port            string
	BaseURL         string
	CodeLength      int
	MaxURLBytes     int
	RateLimitRPS    int
	RateLimitBurst  int
	ReadTimeout     time.Duration
	WriteTimeout    time.Duration
	ShutdownTimeout time.Duration
}

func Load() *Config {
	return &Config{
		Port:            envStr("PORT", "8080"),
		BaseURL:         envStr("BASE_URL", "http://localhost:8080"),
		CodeLength:      envInt("CODE_LENGTH", 7),
		MaxURLBytes:     envInt("MAX_URL_BYTES", 2048),
		RateLimitRPS:    envInt("RATE_LIMIT_RPS", 100),
		RateLimitBurst:  envInt("RATE_LIMIT_BURST", 200),
		ReadTimeout:     envDuration("READ_TIMEOUT", 5*time.Second),
		WriteTimeout:    envDuration("WRITE_TIMEOUT", 10*time.Second),
		ShutdownTimeout: envDuration("SHUTDOWN_TIMEOUT", 10*time.Second),
	}
}

func envStr(key, def string) string {
	if v := os.Getenv(key); v != "" {
		return v
	}
	return def
}

func envInt(key string, def int) int {
	if v := os.Getenv(key); v != "" {
		if n, err := strconv.Atoi(v); err == nil {
			return n
		}
	}
	return def
}

func envDuration(key string, def time.Duration) time.Duration {
	if v := os.Getenv(key); v != "" {
		if d, err := time.ParseDuration(v); err == nil {
			return d
		}
	}
	return def
}

package shortcode

import (
	"crypto/rand"
	"math/big"
	"strings"
)

const alphabet = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"

func Generate(length int) (string, error) {
	var sb strings.Builder
	sb.Grow(length)

	for i := 0; i < length; i++ {
		n, err := rand.Int(rand.Reader, big.NewInt(int64(len(alphabet))))
		if err != nil {
			return "", err
		}
		sb.WriteByte(alphabet[n.Int64()])
	}

	return sb.String(), nil
}

package store

import (
	"sync"
	"time"
)

type Entry struct {
	Code      string    `json:"code"`
	URL       string    `json:"url"`
	CreatedAt time.Time `json:"created_at"`
	Clicks    int64     `json:"clicks"`
}

type ClickRecord struct {
	Timestamp time.Time `json:"timestamp"`
	IP        string    `json:"ip"`
	UserAgent string    `json:"user_agent"`
	Referer   string    `json:"referer"`
}

type Store struct {
	mu      sync.RWMutex
	byCode  map[string]*Entry
	byURL   map[string]string
	clicks  map[string][]ClickRecord
	maxClicks int
}

func New() *Store {
	return &Store{
		byCode:  make(map[string]*Entry),
		byURL:   make(map[string]string),
		clicks:  make(map[string][]ClickRecord),
		maxClicks: 1000,
	}
}

func (s *Store) Set(code, url string) *Entry {
	s.mu.Lock()
	defer s.mu.Unlock()

	if existing, ok := s.byURL[url]; ok {
		return s.byCode[existing]
	}

	entry := &Entry{
		Code:      code,
		URL:       url,
		CreatedAt: time.Now().UTC(),
	}
	s.byCode[code] = entry
	s.byURL[url] = code
	return entry
}

func (s *Store) Get(code string) (*Entry, bool) {
	s.mu.RLock()
	e, ok := s.byCode[code]
	s.mu.RUnlock()
	return e, ok
}

func (s *Store) RecordClick(code, ip, userAgent, referer string) {
	s.mu.Lock()
	defer s.mu.Unlock()

	e, ok := s.byCode[code]
	if !ok {
		return
	}
	e.Clicks++

	rec := ClickRecord{
		Timestamp: time.Now().UTC(),
		IP:        ip,
		UserAgent: userAgent,
		Referer:   referer,
	}
	s.clicks[code] = append(s.clicks[code], rec)
	if len(s.clicks[code]) > s.maxClicks {
		s.clicks[code] = s.clicks[code][len(s.clicks[code])-s.maxClicks:]
	}
}

func (s *Store) Stats(code string) (*Entry, []ClickRecord, bool) {
	s.mu.RLock()
	defer s.mu.RUnlock()

	e, ok := s.byCode[code]
	if !ok {
		return nil, nil, false
	}

	clicks := s.clicks[code]
	out := make([]ClickRecord, len(clicks))
	copy(out, clicks)
	return e, out, true
}

package ratelimit

import (
	"net/http"
	"sync"
	"time"
)

type TokenBucket struct {
	rate   float64
	burst  float64
	tokens float64
	last   time.Time
}

type Limiter struct {
	mu      sync.Mutex
	buckets map[string]*TokenBucket
	rate    float64
	burst   float64
}

func NewLimiter(rps, burst int) *Limiter {
	l := &Limiter{
		buckets: make(map[string]*TokenBucket),
		rate:    float64(rps),
		burst:   float64(burst),
	}
	go l.cleanup(5 * time.Minute)
	return l
}

func (l *Limiter) Allow(key string) bool {
	l.mu.Lock()
	defer l.mu.Unlock()

	b, ok := l.buckets[key]
	if !ok {
		b = &TokenBucket{
			rate:  l.rate,
			burst: l.burst,
			tokens: l.burst,
			last:  time.Now(),
		}
		l.buckets[key] = b
	}

	now := time.Now()
	elapsed := now.Sub(b.last).Seconds()
	b.tokens += elapsed * b.rate
	if b.tokens > b.burst {
		b.tokens = b.burst
	}
	b.last = now

	if b.tokens >= 1 {
		b.tokens--
		return true
	}
	return false
}

func (l *Limiter) cleanup(interval time.Duration) {
	ticker := time.NewTicker(interval)
	defer ticker.Stop()
	for range ticker.C {
		l.mu.Lock()
		cutoff := time.Now().Add(-15 * time.Minute)
		for k, b := range l.buckets {
			if b.last.Before(cutoff) {
				delete(l.buckets, k)
			}
		}
		l.mu.Unlock()
	}
}

func Middleware(l *Limiter) func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			key := r.Header.Get("X-Forwarded-For")
			if key == "" {
				key = r.RemoteAddr
			}
			if !l.Allow(key) {
				http.Error(w, `{"error":"rate limit exceeded"}`, http.StatusTooManyRequests)
				return
			}
			next.ServeHTTP(w, r)
		})
	}
}

