package cmd

import (
	"encoding/json"
	"io"
	"net/http"
	"net/url"
	"strings"

	"github.com/url-shortener/config"
	"github.com/url-shortener/shortcode"
	"github.com/url-shortener/store"
)

type Handler struct {
	store  *store.Store
	config *config.Config
}

func New(s *store.Store, c *config.Config) *Handler {
	return &Handler{store: s, config: c}
}

type shortenRequest struct {
	URL string `json:"url"`
}

type shortenResponse struct {
	Code     string `json:"code"`
	ShortURL string `json:"short_url"`
	LongURL  string `json:"long_url"`
}

type errorResponse struct {
	Error string `json:"error"`
}

func writeJSON(w http.ResponseWriter, status int, v interface{}) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	json.NewEncoder(w).Encode(v)
}

func (h *Handler) Shorten(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeJSON(w, http.StatusMethodNotAllowed, errorResponse{Error: "method not allowed"})
		return
	}

	body, err := io.ReadAll(io.LimitReader(r.Body, int64(h.config.MaxURLBytes)))
	if err != nil {
		writeJSON(w, http.StatusBadRequest, errorResponse{Error: "cannot read body"})
		return
	}
	defer r.Body.Close()

	var req shortenRequest
	if err := json.Unmarshal(body, &req); err != nil {
		writeJSON(w, http.StatusBadRequest, errorResponse{Error: "invalid json"})
		return
	}

	req.URL = strings.TrimSpace(req.URL)
	if req.URL == "" {
		writeJSON(w, http.StatusBadRequest, errorResponse{Error: "url is required"})
		return
	}

	if !strings.HasPrefix(req.URL, "http://") && !strings.HasPrefix(req.URL, "https://") {
		req.URL = "https://" + req.URL
	}

	if _, err := url.ParseRequestURI(req.URL); err != nil {
		writeJSON(w, http.StatusBadRequest, errorResponse{Error: "invalid url"})
		return
	}

	code, err := shortcode.Generate(h.config.CodeLength)
	if err != nil {
		writeJSON(w, http.StatusInternalServerError, errorResponse{Error: "code generation failed"})
		return
	}

	entry := h.store.Set(code, req.URL)
	resp := shortenResponse{
		Code:     entry.Code,
		ShortURL: h.config.BaseURL + "/" + entry.Code,
		LongURL:  entry.URL,
	}
	writeJSON(w, http.StatusCreated, resp)
}

func (h *Handler) Redirect(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		writeJSON(w, http.StatusMethodNotAllowed, errorResponse{Error: "method not allowed"})
		return
	}

	code := strings.TrimPrefix(r.URL.Path, "/")
	if idx := strings.IndexByte(code, '/'); idx != -1 {
		code = code[:idx]
	}

	entry, ok := h.store.Get(code)
	if !ok {
		writeJSON(w, http.StatusNotFound, errorResponse{Error: "not found"})
		return
	}

	ip := r.Header.Get("X-Forwarded-For")
	if ip == "" {
		ip = r.RemoteAddr
	}
	h.store.RecordClick(code, ip, r.UserAgent(), r.Referer())

	http.Redirect(w, r, entry.URL, http.StatusMovedPermanently)
}

func (h *Handler) Analytics(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		writeJSON(w, http.StatusMethodNotAllowed, errorResponse{Error: "method not allowed"})
		return
	}

	code := strings.TrimPrefix(r.URL.Path, "/analytics/")

	entry, clicks, ok := h.store.Stats(code)
	if !ok {
		writeJSON(w, http.StatusNotFound, errorResponse{Error: "not found"})
		return
	}

	response := struct {
		Code      string             `json:"code"`
		LongURL   string             `json:"long_url"`
		Clicks    int64              `json:"total_clicks"`
		CreatedAt string             `json:"created_at"`
		History   []store.ClickRecord `json:"recent_clicks"`
	}{
		Code:      entry.Code,
		LongURL:   entry.URL,
		Clicks:    entry.Clicks,
		CreatedAt: entry.CreatedAt.Format("2006-01-02T15:04:05Z"),
		History:   clicks,
	}

	writeJSON(w, http.StatusOK, response)
}

package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"

	"github.com/url-shortener/cmd"
	"github.com/url-shortener/config"
	"github.com/url-shortener/store"
)

func TestShorten(t *testing.T) {
	st := store.New()
	cfg := config.Load()
	h := cmd.New(st, cfg)

	body := `{"url":"https://example.com/very/long/path"}`
	req := httptest.NewRequest(http.MethodPost, "/shorten", strings.NewReader(body))
	req.Header.Set("Content-Type", "application/json")
	w := httptest.NewRecorder()

	h.Shorten(w, req)

	resp := w.Result()
	if resp.StatusCode != http.StatusCreated {
		t.Fatalf("expected 201, got %d", resp.StatusCode)
	}

	var sr cmd.ShortenResponse // reusing the type; it's unexported but in test
	// Actually, let's just decode to map
	var m map[string]interface{}
	json.NewDecoder(resp.Body).Decode(&m)
	if m["short_url"] == nil || m["short_url"] == "" {
		t.Fatal("expected short_url in response")
	}
	if m["code"] == nil || m["code"] == "" {
		t.Fatal("expected code in response")
	}
}

func TestRedirect(t *testing.T) {
	st := store.New()
	cfg := config.Load()
	h := cmd.New(st, cfg)

	st.Set("abc123", "https://example.com")

	req := httptest.NewRequest(http.MethodGet, "/abc123", nil)
	w := httptest.NewRecorder()

	h.Redirect(w, req)

	resp := w.Result()
	if resp.StatusCode != http.StatusMovedPermanently {
		t.Fatalf("expected 301, got %d", resp.StatusCode)
	}
	loc := resp.Header.Get("Location")
	if loc != "https://example.com" {
		t.Fatalf("expected https://example.com, got %s", loc)
	}

	entry, _ := st.Get("abc123")
	if entry.Clicks != 1 {
		t.Fatalf("expected 1 click, got %d", entry.Clicks)
	}
}

func TestAnalytics(t *testing.T) {
	st := store.New()
	cfg := config.Load()
	h := cmd.New(st, cfg)

	st.Set("abc123", "https://example.com")
	st.RecordClick("abc123", "1.2.3.4", "GoTest", "")

	req := httptest.NewRequest(http.MethodGet, "/analytics/abc123", nil)
	w := httptest.NewRecorder()

	h.Analytics(w, req)

	resp := w.Result()
	if resp.StatusCode != http.StatusOK {
		t.Fatalf("expected 200, got %d", resp.StatusCode)
	}

	var m map[string]interface{}
	json.NewDecoder(resp.Body).Decode(&m)
	if m["total_clicks"].(float64) != 1 {
		t.Fatalf("expected 1 click, got %v", m["total_clicks"])
	}
}

func TestNotFound(t *testing.T) {
	st := store.New()
	cfg := config.Load()
	h := cmd.New(st, cfg)

	req := httptest.NewRequest(http.MethodGet, "/nonexistent", nil)
	w := httptest.NewRecorder()

	h.Redirect(w, req)

	resp := w.Result()
	if resp.StatusCode != http.StatusNotFound {
		t.Fatalf("expected 404, got %d", resp.StatusCode)
	}
}

func BenchmarkShorten(b *testing.B) {
	st := store.New()
	cfg := config.Load()
	h := cmd.New(st, cfg)

	body := `{"url":"https://example.com/path"}`
	b.ResetTimer()
	b.ReportAllocs()

	for i := 0; i < b.N; i++ {
		req := httptest.NewRequest(http.MethodPost, "/shorten", strings.NewReader(body))
		req.Header.Set("Content-Type", "application/json")
		w := httptest.NewRecorder()
		h.Shorten(w, req)

		if w.Code != http.StatusCreated {
			b.Fatalf("expected 201, got %d", w.Code)
		}
	}
}

func BenchmarkRedirect(b *testing.B) {
	st := store.New()
	cfg := config.Load()
	h := cmd.New(st, cfg)

	st.Set("abc123", "https://example.com")
	b.ResetTimer()
	b.ReportAllocs()

	for i := 0; i < b.N; i++ {
		req := httptest.NewRequest(http.MethodGet, "/abc123", nil)
		w := httptest.NewRecorder()
		h.Redirect(w, req)

		if w.Code != http.StatusMovedPermanently {
			b.Fatalf("expected 301, got %d", w.Code)
		}
	}
}

func BenchmarkAnalytics(b *testing.B) {
	st := store.New()
	cfg := config.Load()
	h := cmd.New(st, cfg)

	st.Set("abc123", "https://example.com")
	st.RecordClick("abc123", "1.2.3.4", "GoBench", "")
	b.ResetTimer()
	b.ReportAllocs()

	for i := 0; i < b.N; i++ {
		req := httptest.NewRequest(http.MethodGet, "/analytics/abc123", nil)
		w := httptest.NewRecorder()
		h.Analytics(w, req)

		if w.Code != http.StatusOK {
			b.Fatalf("expected 200, got %d", w.Code)
		}
	}
}

func BenchmarkShortenParallel(b *testing.B) {
	st := store.New()
	cfg := config.Load()
	h := cmd.New(st, cfg)

	b.ResetTimer()
	b.ReportAllocs()
	b.RunParallel(func(pb *testing.PB) {
		body := `{"url":"https://example.com/path"}`
		for pb.Next() {
			req := httptest.NewRequest(http.MethodPost, "/shorten", strings.NewReader(body))
			req.Header.Set("Content-Type", "application/json")
			w := httptest.NewRecorder()
			h.Shorten(w, req)
		}
	})
}

func BenchmarkRedirectParallel(b *testing.B) {
	st := store.New()
	cfg := config.Load()
	h := cmd.New(st, cfg)

	st.Set("abc123", "https://example.com")
	b.ResetTimer()
	b.ReportAllocs()
	b.RunParallel(func(pb *testing.PB) {
		for pb.Next() {
			req := httptest.NewRequest(http.MethodGet, "/abc123", nil)
			w := httptest.NewRecorder()
			h.Redirect(w, req)
		}
	})
}

func runHTTPBenchmarks() {
	ports := []int{8081, 8082, 8083}
	for _, port := range ports {
		go func(p int) {
			mux := http.NewServeMux()
			st := store.New()
			cfg := config.Load()
			cfg.Port = fmt.Sprintf("%d", p)
			h := cmd.New(st, cfg)
			mux.HandleFunc("/shorten", h.Shorten)
			mux.HandleFunc("/analytics/", h.Analytics)
			mux.HandleFunc("/", h.Redirect)
			http.ListenAndServe(fmt.Sprintf(":%d", p), mux)
		}(port)
	}
	select {}
}

// HTTP-level benchmark with real HTTP connections
func BenchmarkHTTPServe(b *testing.B) {
	st := store.New()
	cfg := config.Load()
	h := cmd.New(st, cfg)

	mux := http.NewServeMux()
	mux.HandleFunc("/shorten", h.Shorten)
	mux.HandleFunc("/analytics/", h.Analytics)
	mux.HandleFunc("/", h.Redirect)

	ts := httptest.NewServer(mux)
	defer ts.Close()

	st.Set("abc123", "https://example.com")

	client := &http.Client{
		Transport: &http.Transport{
			DisableKeepAlives: false,
			MaxConnsPerHost:   1000,
		},
	}

	body := `{"url":"https://example.com/path"}`
	b.ResetTimer()
	b.ReportAllocs()
	b.RunParallel(func(pb *testing.PB) {
		for pb.Next() {
			resp, err := client.Get(ts.URL + "/abc123")
			if err != nil {
				b.Fatal(err)
			}
			io.Copy(io.Discard, resp.Body)
			resp.Body.Close()
		}
	})
	b.StopTimer()
	_ = body
}

func BenchmarkShortenDupe(b *testing.B) {
	st := store.New()
	cfg := config.Load()
	h := cmd.New(st, cfg)

	st.Set("abc123", "https://example.com/path")
	body := `{"url":"https://example.com/path"}`
	b.ResetTimer()
	b.ReportAllocs()

	for i := 0; i < b.N; i++ {
		req := httptest.NewRequest(http.MethodPost, "/shorten", bytes.NewReader([]byte(body)))
		req.Header.Set("Content-Type", "application/json")
		w := httptest.NewRecorder()
		h.Shorten(w, req)
	}
}

